// The logos of the tools the site names, drawn inline so they cost no
// request. Brand marks come from Simple Icons 16.34.0 (CC0), in their brand
// colour, lightened where needed to stand out on the night background; the
// AWS icons from the AWS Architecture Icons; the logos of External Secrets,
// k3d, Sloth and Langfuse from their own repositories (k3d's black strokes
// turned light, so they show on the night; Sloth's only logo is a PNG). Each
// mark belongs to its owner, and is shown only to say which tool a project
// uses.

/** `aspect` is width over height, for a logo that is not square. */
type Mark = { title: string; viewBox: string; body: string; aspect?: number };

// Relative luminance, as WCAG defines it.
const luminance = (rgb: number[]) => {
  const [r, g, b] = rgb.map((c) => {
    const s = c / 255;
    return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};

// --card, the darkest surface a logo sits on.
const surface = luminance([0x0b, 0x15, 0x24]);

// The brand colour, mixed with white until it reaches a contrast of 3:1, the
// minimum WCAG asks of a graphic. Most brand colours already do. A black mark
// turns white instead of grey, as brands draw it on a dark background.
const readable = (hex: string) => {
  const rgb = [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16));
  if (luminance(rgb) < 0.03) return '#e6f0ff';
  for (let step = 0; step <= 20; step++) {
    const mixed = rgb.map((c) => Math.round(c + ((255 - c) * step) / 20));
    if ((luminance(mixed) + 0.05) / (surface + 0.05) >= 3) {
      return `#${mixed.map((c) => c.toString(16).padStart(2, '0')).join('')}`;
    }
  }
  return '#ffffff';
};

const brand = (title: string, hex: string, path: string): Mark => ({
  title,
  viewBox: '0 0 24 24',
  body: `<path fill="${readable(hex)}" d="${path}"/>`,
});

